INSERT INTO public.app_iku_uraian (ref_iku, uraian, updated_by) VALUES ('[IKU 1.2] Persentase mahasiswa S1 dan D4/D3/D2/D1 yang menjalankan kegiatan pembelajaran di luar program studi atau meraih prestasi', '', 'Master Bawaan 2025') ON CONFLICT (ref_iku) DO UPDATE SET uraian = EXCLUDED.uraian;
INSERT INTO public.app_iku_uraian (ref_iku, uraian, updated_by) VALUES ('[IKU 2.1] Persentase dosen yang berkegiatan tridharma di perguruan tinggi lain, bekerja sebagai praktisi di dunia industri, atau membimbing mahasiswa berkegiatan di luar program studi', '', 'Master Bawaan 2025') ON CONFLICT (ref_iku) DO UPDATE SET uraian = EXCLUDED.uraian;
INSERT INTO public.app_iku_uraian (ref_iku, uraian, updated_by) VALUES ('[IKU 2.2] Persentase dosen yang memiliki sertifikat kompetensi/profesi yang diakui oleh dunia usaha dan dunia industri atau persentase pengajar yang berasal dari kalangan praktisi profesional, dunia usaha, atau dunia industri', '', 'Master Bawaan 2025') ON CONFLICT (ref_iku) DO UPDATE SET uraian = EXCLUDED.uraian;
INSERT INTO public.app_iku_uraian (ref_iku, uraian, updated_by) VALUES ('[IKU 2.3] Jumlah keluaran dosen yang berhasil mendapatkan rekognisi internasional atau diterapkan oleh masyarakat/industri/pemerintah per jumlah dosen', '', 'Master Bawaan 2025') ON CONFLICT (ref_iku) DO UPDATE SET uraian = EXCLUDED.uraian;
INSERT INTO public.app_iku_uraian (ref_iku, uraian, updated_by) VALUES ('[IKU 3.1] Jumlah kerjasama per program studi S1 dan D4/D3/D2/D1', '', 'Master Bawaan 2025') ON CONFLICT (ref_iku) DO UPDATE SET uraian = EXCLUDED.uraian;
INSERT INTO public.app_iku_uraian (ref_iku, uraian, updated_by) VALUES ('[IKU 3.2] Persentase mata kuliah S1 dan D4/D3/D2/D1 yang menggunakan metode pembelajaran pemecahan kasus (case method) atau pembelajaran kelompok berbasis project (teambased project) sebagai bagian dari bobot evaluasi', '', 'Master Bawaan 2025') ON CONFLICT (ref_iku) DO UPDATE SET uraian = EXCLUDED.uraian;
INSERT INTO public.app_iku_uraian (ref_iku, uraian, updated_by) VALUES ('[IKU 3.3] Persentase program studi S1 dan D4/D3 yang memiliki akreditasi atau sertifikasi internasional yang diakui pemerintah', '', 'Master Bawaan 2025') ON CONFLICT (ref_iku) DO UPDATE SET uraian = EXCLUDED.uraian;
